export const heapSource =
  '/** Trusted editorial implementation. Never expose before solution unlock. */\nexport class MinHeap<T> {\n  private items: T[] = [];\n  constructor(private compare: (a: T, b: T) => number) {}\n  get size(): number {\n    return this.items.length;\n  }\n  peek(): T {\n    if (!this.size) throw new Error("Fila vazia");\n    return this.items[0];\n  }\n  push(item: T): void {\n    const a = this.items;\n    let index = a.push(item) - 1;\n    while (index > 0) {\n      const parent = Math.floor((index - 1) / 2);\n      if (this.compare(a[parent], a[index]) <= 0) break;\n      [a[parent], a[index]] = [a[index], a[parent]];\n      index = parent;\n    }\n  }\n  pop(): T {\n    if (!this.size) throw new Error("Fila vazia");\n    const a = this.items,\n      first = a[0],\n      last = a.pop()!;\n    if (a.length) {\n      a[0] = last;\n      let index = 0;\n      while (2 * index + 1 < a.length) {\n        let child = 2 * index + 1;\n        if (child + 1 < a.length && this.compare(a[child + 1], a[child]) < 0)\n          child++;\n        if (this.compare(a[index], a[child]) <= 0) break;\n        [a[index], a[child]] = [a[child], a[index]];\n        index = child;\n      }\n    }\n    return first;\n  }\n}\n';
export const shortestPathSource =
  'import { MinHeap } from "./min-heap";\n\nexport type Graph = ReadonlyArray<ReadonlyArray<{ to: number; weight: number }>>;\n\nexport function shortestPath(\n  graph: Graph,\n  start: number,\n  end: number,\n): number[] {\n  const distance = Array<number>(graph.length).fill(Infinity);\n  const previous = Array<number>(graph.length).fill(-1);\n  const heap = new MinHeap<[number, number]>((a, b) => a[0] - b[0]);\n  distance[start] = 0;\n  heap.push([0, start]);\n  while (heap.size) {\n    const [cost, vertex] = heap.pop();\n    if (cost !== distance[vertex]) continue;\n    if (vertex === end) break;\n    for (const { to, weight } of graph[vertex]) {\n      const candidate = cost + weight;\n      if (candidate < distance[to]) {\n        distance[to] = candidate;\n        previous[to] = vertex;\n        heap.push([candidate, to]);\n      }\n    }\n  }\n  if (distance[end] === Infinity) return [];\n  const path: number[] = [];\n  for (let vertex = end; vertex !== -1; vertex = previous[vertex])\n    path.push(vertex);\n  return path.reverse();\n}\n';
